BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (1127::BIGINT, 'Un curso complejo que la profe hace muy ameno, pero tiene que poner de su parte. El proyecto y las tareas pueden ser rudos pero ella es muy accesible y ayuda un montón, a veces cuesta que conteste correos. Todos los que ya han llevado con ella saben que muy buena como profe y como persona.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '01d9cd1c82887f5ecb89fab38bdc798358f6a1982990bac073dcbf81c40c4468'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'La profesora siempre esta dispuesta a ayudar a quien lo ocupe, y es super comprensiva, si uno no entiende algo, ella te explica cuantas veces sea necesario. El proyecto es bastante pesado, pero ella siempre esta dispuesta a ayudar en lo que pueda. Es una profesora con la que se disfruta la clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-12-21T00:00:00+00:00'::TIMESTAMPTZ, '15956101199e2826b93e498e4f789cec216a6ef3b346bfe27223fc14c62a93b2'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'Todos los cursos que he llevado con ella han sido increíbles, es una hermosa persona y una excelente profesora. Puede que el curso sea complicado, pero es muy llevadero, pensaba que no me gustaba tanto la mecánica hasta que llevé este curso. Los proyectos son difíciles, pero muy gratificantes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '677ffb02f7c470182800a1a5ffc22f6a34e4d1f4976b97ef9f40d773e5be8ac6'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'No ayuda en el proyecto ni da clases, uno queda mucho a la libre.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '512f325f698d5ec827ccbd779f285a971ebbdef0b03bcf134c24c73fb9e38199'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Buena profe, explica bien y aclara dudas cuando se le pregunta. A veces tarda mucho en responder mensajes, y en general califica duro los trabajos, pero para este curso en particular eso no afectó tanto. También dura mucho en publicar las notas, pero en general es una buena opción de matrícula'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a2210dcf11e3c1da0ce8c0e2e13f6b4225596f28b80bf835c5f2bfa9aa34d359'::TEXT, ARRAY[3065]::BIGINT[]),
    (1127::BIGINT, 'La profesora explica bien la teoría, pero casi no hace ejercicios, ni cosas practicas. Solo en los tareas hacemos ejercicios y casi nunca da retroalimentación para saber si lo estamos haciendo bien o en qué nos equivocamos. Los exámenes suelen ser muy largos, con poco tiempo y califica duro.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a185d89ee8f601da66c46b7b88836268055d08910dab7a0fa2957d019c1bb1db'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Es una excelente profesora muy dedicada y ordenada. Las clases son buenas, pero las evaluaciones son muy difíciles en comparación con tareas o ejercicios de clase. Es importante llevar la materia al día y buscar un buen equipo para tareas de diseño (Verilog). Es la mejor opción para el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e7fe197ab3c07dc32e90db7633634282429404425f110a78f394a481cbfe2457'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Muy buena profe, se preocupa porque uno entienda, sin embargo, en la parte de proyectos uno queda muy libre por lo que ella no está pendiente de los avances y se puede juntar todo para el final. Duró un poco dando el feedback de los laboratorios, sin embargo, los revisa muy profundo y justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2022-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'f39958810da36ee7ac8a283a1652e1c1be2c07e585d90d1103892f686b10a9a1'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Explica muy claro, sin embargo la materia es muy extensa, por lo que es recomendable recurrir al libro para abarcar todo los detalles que se necesitan para realizar las tareas. Los ejercicios de los quizes tienden a ser más complicados que los ejemplos mostrados en clase y el proyecto es largo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, '3e3d67009f758b9a4a58c803e9bece4bbd8474aa997d8c4f0f7c65b330106959'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'El curso en sí tiene un nivel de dificultad alto, pero la profe lo hace las clases entretenidas y se entiende todo bastante bien. Hace los quices un poco difíciles entonces hay que estudiar bastantillo. Al final dió 10% de la nota por participación y fue increible.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'fa1e8ab33ff4d3317cd89fffae3c69f5ffbf37c5e2e68446ba9a689d72a44b80'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'Pese a que el curso como tal es pesado, la profe explica muy bien la materia, y da buena retroalimentación en los trabajos. Revisa todo con mucho detalle, y por lo tanto dura en entregar notas. Es estricta al evaluar, pero al mismo tiempo ayuda mucho.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f23781fc909ccb86685e3554c6a3700cf0fb92ba6026e13a2b6764062c51a13a'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'Es joven, por lo que se ven ganas de enseñar y tiene un buen conocimiento de la materia. Las clases fueron buenas y nada estresantes o tediosas, puede tardar algo en atender fuera de clase pero es entendible y aún así se nota interés por resolver consultas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '4c7bb889b761dbedfe1efba029c8f2995bb0270a7f131b303468cbd55f99535e'::TEXT, ARRAY[3050]::BIGINT[]),
    (1127::BIGINT, 'Yo le dije a la profe que se casara conmigo, pero no quiso jaja xd. Súper ordenada, se preocupa por el estudiante, califica justo y siempre brinda buena retroalimentación. Uno de los mejores profes que he tenido.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-14T00:00:00+00:00'::TIMESTAMPTZ, 'dc479087948caa82dc2314142825779ff111966f8b39360fd499746c15fa4604'::TEXT, ARRAY[3065]::BIGINT[]),
    (1127::BIGINT, 'Excelente profe, es muy ordenada y explica bien. Califica con lupa y por eso tarda un poco en dar las evaluaciones, pero da muy buena retroalimentación del trabajo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'fb157372edfa301e673e8383974614a9d374df54a951505defde96647ee1a961'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'Lo mejor del Área Académica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7b7699ae98f97395e8c7e5331f262120d39ee0f43463398c83526d1c7563722e'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Excelente profesora para un curso que es tan pesado, de verdad se esmera por que los estudiantes aprendan. Sí puede llegar a ser un poco dura para calificar, pero su calidad como profesora lo justifica.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '497b4ac0c2acdd30cefc237ec65e305b0aaac179272cb105c9b5eb53e3aac1be'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'Excelente profe, muy buena persona, amable, explica muy claro, escucha sugerencias. Califica muy suave las prácticas semanales, pero puede calificar MUY duro ciertas cosas principalmente: en formatos de entrega, y los exámenes en Gradescope. El curso DEBE tener mucha más materia, o ser más profundo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '5a5e46e3213ee8dc68857c93270cc40ba51384b584c6785ca86d4f03d25a1c23'::TEXT, ARRAY[3065]::BIGINT[]),
    (1127::BIGINT, 'Es buena profesora, califica muy duro y las retroalimentaciones a veces son muy ambiguas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '82cdddfcf831ba9823c2aaa6ebc4523caa421814b7cfdb7dd99fcbd67b551a8a'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Promete y medio.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '536e5b3276a40b73adbc1944ba2bc21febd966a1a27a06c91a429ccc20e6be2d'::TEXT, ARRAY[3065]::BIGINT[]),
    (1127::BIGINT, 'En comparación con otros profesores que han dado el curso es increíble lo que se puede aprender con ella, lleva todas las clases super preparadas, es clara y enseña tips para la vida y la calle. Lo mejor que le pudo haber pasado a este curso y a mi fue que le dejaran el curso solo a ella! La amo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-09T00:00:00+00:00'::TIMESTAMPTZ, '2e6022fcacbebc312b456b55fc870f4f34536813a988e899e05996bd1f842279'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, 'Para clases virtuales se manejó a puras guías de estudio, nunca se entregó enunciado para el proyecto, entonces todos tenían ideas diferentes sobre qué entregar. Muchas cosas fueron ideas de Jaime, tal vez sea más llevadero si solo ella da el curso. Eso sí es buena gente y revisa suave.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '79b56b3e095ed6967dd5549be0de84fe398236f96804b976cc5a3e5416eb1754'::TEXT, ARRAY[3068]::BIGINT[]),
    (1127::BIGINT, '(Curso virtual) El curso se redujo a guías de estudio semanales y algunos videos explicativos. Se perdió la experiencia del laboratorio y los exámenes tenían una dificultad desproporcionada, los elaboraba el otro profesor.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'c2e74775534501819e5268a0b8037add5a11b64f21fc7c402d1548a9c608086e'::TEXT, ARRAY[3065]::BIGINT[]),
    (1127::BIGINT, 'Buena profesora, comprensible y orienta al estudiante de buena manera :D (Debido al Covid el cursó se resumió en 3 proyectos, 1 fue físico pre-pandemia y los otros dos en Verilog).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'fabe740708e03c9cf9650ee7dd996840eced107e13795fa6d7a37e587a5dbb72'::TEXT, ARRAY[3056]::BIGINT[]),
    (1127::BIGINT, 'Excelente profesora, es joven y no tiene esa actitud tan terrible que tienen muchos profes del tec.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, '7fa8c6dbc7a0e79b9db21c9ad800030ff41b39cdd9235e0b52e996dbb64d1f3b'::TEXT, ARRAY[3050]::BIGINT[]),
    (1127::BIGINT, 'Primera vez que da el curso. Diseño es muy importante, pero vimos casi que solo la mitad de los temas. Intenta que entendamos la materia, pero aun le falta experiencia dando cursos. Aparte de todo eso, creo que con el tiempo sera una profesora excelente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '97564c45273842e656c0a1caa7f9edd48f4cb4fe24045e106227dfe9b2463d45'::TEXT, ARRAY[3068]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
